def grasp_and_test_lift(arm, grasp_pose, lift_pose, action_budget=35, close_steps=8):
    obs = get_observation()
    obs, report = move_ee(arm, grasp_pose, 0.0, max_steps=min(close_steps, action_budget), min_steps=min(close_steps, action_budget))
